functions.searchTracks:
async function searchTracks(token, query, offset = 0) {
  queriesAttemptedThisGeneration.add(canonicalQuery(query));
  const cached = readSearchCache(query, offset);
  if (cached) {
    const validCached = cached.filter(track => queryMatchesTrack(query, track));
    let acquiredAt = Date.now();
    try { acquiredAt = JSON.parse(localStorage.getItem(searchCacheKey(query, offset))).savedAt; } catch {}
    addToCandidatePool(query, validCached, { fromCache: true, acquiredAt });
    return validCached;
  }

  if (newSearchesThisGeneration >= maxNewSearchesThisGeneration) {
    return [];
  }
  newSearchesThisGeneration++;

  const url = new URL("https://api.spotify.com/v1/search");
  url.search = new URLSearchParams({
    q: query,
    type: "track",
    limit: "10",
    offset: String(offset)
  }).toString();

  const authState = { retried: false };
  for (let attempt = 0; attempt <= MAX_RATE_LIMIT_RETRIES; attempt++) {
    if (activeGenerationProgress) await activeGenerationProgress.measureAsync("throttle", waitForSearchSlot);
    else await waitForSearchSlot();

    const response = await spotifyGenerationRequest(token, url, {
      headers: { Authorization: `Bearer ${token}` }
    }, authState);

    const data = await parseJsonSafely(response);

    if (response.ok) {
      const items = (data?.tracks?.items || []).filter(track => queryMatchesTrack(query, track));
      writeSearchCache(query, offset, items);
      addToCandidatePool(query, items);
      return items;
    }

    if (response.status === 429) {
      const reason = data?.error?.reason;
      if (reason === "QUOTA_EXCEEDED") {
        throw new Error(
          "Spotify: wyczerpano quota aplikacji w Development Mode. To nie jest chwilowy limit szybkości. Odczekaj do odnowienia limitu i spróbuj ponownie później."
        );
      }

      const retryAfterHeader = Number(response.headers.get("Retry-After"));
      const retrySeconds = Number.isFinite(retryAfterHeader) && retryAfterHeader > 0
        ? retryAfterHeader
        : Math.min(30, 2 ** attempt * 2);

      if (attempt >= MAX_RATE_LIMIT_RETRIES) {
        throw new Error(
          `Spotify nadal ogranicza liczbę zapytań (429). Ostatnie Retry-After: ${retrySeconds} s.`
        );
      }

      generationNote(`Spotify ogranicza zapytania (429). Czekam ${retrySeconds} s i próbuję ponownie…`);
      if (activeGenerationProgress) await activeGenerationProgress.measureAsync("retryWait", () => sleep(retrySeconds * 1000 + 250));
      else await sleep(retrySeconds * 1000 + 250);
      continue;
    }

    console.error(data);
    const message = data?.error?.message ? `: ${data.error.message}` : "";
    throw new Error(`Błąd wyszukiwania Spotify: ${response.status}${message}`);
  }

  return [];
}

functions.addToCandidatePool:
function addToCandidatePool(query, items, { fromCache = false, acquiredAt = Date.now() } = {}) {
  if (!query || !Array.isArray(items) || !items.length) return;
  const pool = loadCandidatePool();
  const map = new Map(pool.map(item => [item.track.id, item]));
  const now = Date.now();

  for (const track of items) {
    if (!track?.id || !track?.uri) continue;
    if (!queryMatchesTrack(query, track)) continue;
    const existing = map.get(track.id);
    if (existing) {
      if (!fromCache) existing.savedAt = now;
      existing.lastUsedAt = now;
      existing.track = slimTrack(track);
      const mergedQueries = [...(existing.queries || []), query];
      const seen = new Set();
      existing.queries = mergedQueries.filter(item => {
        const key = canonicalQuery(item);
        if (!key || seen.has(key)) return false;
        seen.add(key);
        return true;
      });
    } else {
      map.set(track.id, {
        track: slimTrack(track),
        queries: [query],
        savedAt: fromCache ? acquiredAt : now,
        lastUsedAt: now
      });
    }
  }

  saveCandidatePool([...map.values()]);
  if (typeof historySummary !== "undefined" && historySummary) renderHistorySummary();
}

functions.eligibleGroupCandidates:
function eligibleGroupCandidates(selected, blocklists, ctx, rows = loadCandidatePool(), canonicalRows = rows) {
  rebuildCanonicalCleanVariantSignatures(canonicalRows, ctx.acquisitionVariantArtists || null);
  const stats = newRejectionStats(rows.length);
  const eligible = [];
  const artistFeedback = ctx.retentionFeedback?.artistStats || feedbackArtistStats();
  const seenIds = new Set();

  for (const row of rows) {
    const track = row?.track;
    if (!track?.id || !track?.uri || seenIds.has(track.id)) {
      stats.invalid++;
      continue;
    }
    seenIds.add(track.id);

    if (trackHasArtistExclusion(track)) {
      stats.artistIdExcluded++;
      continue;
    }
    if ((ctx.retentionSnapshot ? Number(ctx.retentionSnapshot.feedback[trackSignature(track)]?.value || 0) : trackFeedbackValue(track)) < 0) {
      stats.feedbackTrack++;
      continue;
    }
    if (looksLikeUnwantedVariant(track, ctx.acquisitionVariantArtists || null)) {
      stats.unwantedVariant++;
      continue;
    }

    const artistIds = (track.artists || []).map(a => a?.id || "").filter(Boolean);
    const artistNames = (track.artists || []).map(a => normalizeArtistName(a?.name || "")).filter(Boolean);

    if (artistNames.some(name => blocklists.explicitBlockedNames.has(name))) {
      stats.explicitBlockedArtist++;
      continue;
    }
    if (artistNames.some(name => blocklists.feedbackBlockedNames.has(name))) {
      stats.feedbackBlockedArtist++;
      continue;
    }
    if (hasStrongNegativeArtistFeedback(track, artistFeedback)) {
      stats.strongNegativeArtistFeedback++;
      continue;
    }
    if (
      artistIds.some(id => blocklists.blockedArtists.has(id)) ||
      artistNames.some(name => blocklists.historyBlockedNames.has(name))
    ) {
      stats.artistCooldown++;
      continue;
    }

    const signature = trackSignature(track);
    const duplicateSignatures = trackDuplicateSignatures(track);
    if (
      blocklists.blockedTracks.has(track.id) ||
      (signature && blocklists.blockedTrackSignatures.has(signature)) ||
      duplicateSignatures.some(key => blocklists.blockedTrackSignatures.has(key))
    ) {
      stats.recentTrack++;
      continue;
    }

    const staticInfo = groupCandidateStatic(track, ctx);
    if (!satisfiesIndividualMinimum(staticInfo, ctx)) {
      stats.lowIndividualFit++;
      continue;
    }
    const strongTasteDiscovery =
      Number(discoveryLevel.value || 0) > 0 &&
      staticInfo.maxScore >= 72 &&
      (staticInfo.likedByAny || staticInfo.seedByAny);

    if (!recognizabilityPass(track, ctx.retentionSnapshot) && !strongTasteDiscovery) {
      stats.recognizability++;
      continue;
    }

    if (staticInfo.groupBase < 34 || staticInfo.maxScore < 45) {
      stats.lowGroupFit++;
      continue;
    }

    eligible.push(staticInfo);
    stats.eligible++;
  }

  return { eligible, stats };
}

functions.writeSearchCache:
function writeSearchCache(query, offset, items) {
  try {
    localStorage.setItem(
      searchCacheKey(query, offset),
      JSON.stringify({ savedAt: Date.now(), items })
    );
  } catch (err) {
    console.warn("Nie udało się zapisać cache wyszukiwania.", err);
  }
}
